<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=esc($title)?></title><link rel="stylesheet" href="<?=base_url('styles.css')?>"><style>body{background:#090b0d;color:#eee}.wrap{max-width:1100px;margin:auto;padding:30px}.top{display:flex;justify-content:space-between;gap:15px}.btn{padding:10px 14px;border:1px solid #444;border-radius:9px;background:#171717;color:#e8d4ac;text-decoration:none}.primary{background:#c6a66e;color:#111}.card{margin-top:18px;padding:22px;border:1px solid #292929;border-radius:18px;background:#111416}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid #2b2b2b;text-align:left}.form{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.form input,.form select{padding:10px;background:#0d0f10;color:#eee;border:1px solid #333;border-radius:8px}.muted{color:#999;font-size:11px}.actions{display:flex;gap:8px;flex-wrap:wrap}@media(max-width:750px){.grid,.form{grid-template-columns:1fr}.top{display:block}.actions{margin-top:12px}}</style></head><body><div class="wrap"><div class="top"><div><div class="muted">ACTUAL / PROFESSIONAL INVOICE</div><h1 style="font:500 38px Georgia,serif"><?=esc($invoice['invoice_no'])?></h1><div class="muted"><?=esc($invoice['client_name'])?></div></div><div class="actions"><a class="btn" href="<?=site_url('admin/invoices')?>">← Back</a><a class="btn" target="_blank" href="<?=site_url('admin/invoices/'.$invoice['id'].'/print?autoprint=1')?>">Print</a><a class="btn primary" href="<?=site_url('admin/invoices/'.$invoice['id'].'/pdf')?>">Download PDF</a></div></div><?php if(session('success')):?><div class="card" style="color:#bce5cb"><?=esc(session('success'))?></div><?php endif;?><?php if(session('error')):?><div class="card" style="color:#ffc7c2"><?=esc(session('error'))?></div><?php endif;?><div class="grid"><div class="card"><div class="muted">BILL TO</div><h2><?=esc($invoice['client_name'])?></h2><p><?=nl2br(esc($invoice['client_address']))?><br><?=esc($invoice['client_email'])?><br><?=esc($invoice['client_phone'])?></p><b>Matter:</b> <?=esc($invoice['case_reference']?:'—')?></div><div class="card"><div class="muted">PAYMENT</div><h2><?=esc($invoice['payment_status'])?></h2><p>Total <b>₹ <?=number_format($invoice['total'],2)?></b><br>Paid <b>₹ <?=number_format($paid,2)?></b><br>Outstanding <b>₹ <?=number_format(max(0,$invoice['total']-$paid),2)?></b></p></div></div><div class="card"><h2 style="font:500 25px Georgia,serif">Professional charges</h2><table class="table"><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Amount</th></tr><?php foreach($items as $x):?><tr><td><?=nl2br(esc($x['description']))?></td><td><?=rtrim(rtrim(number_format($x['quantity'],2), '0'),'.')?></td><td>₹ <?=number_format($x['rate'],2)?></td><td>₹ <?=number_format($x['amount'],2)?></td></tr><?php endforeach;?><tr><td colspan="3"><b>Subtotal</b></td><td><b>₹ <?=number_format($invoice['subtotal'],2)?></b></td></tr></table></div><div class="card"><h2 style="font:500 25px Georgia,serif">Record payment</h2><form class="form" method="post" action="<?=site_url('admin/invoices/'.$invoice['id'].'/payment')?>"><?=csrf_field()?><input type="date" name="payment_date" value="<?=date('Y-m-d')?>"><input type="number" step=".01" min=".01" name="amount" placeholder="Amount" required><select name="method"><option>Online/Wire Transfer</option><option>UPI</option><option>Cash</option><option>Cheque</option></select><input name="reference_no" placeholder="Reference"><button class="btn primary">Record</button></form><?php if($payments):?><table class="table" style="margin-top:15px"><tr><th>Date</th><th>Method</th><th>Reference</th><th>Amount</th></tr><?php foreach($payments as $p):?><tr><td><?=date('d M Y',strtotime($p['payment_date']))?></td><td><?=esc($p['method'])?></td><td><?=esc($p['reference_no']?:'—')?></td><td>₹ <?=number_format($p['amount'],2)?></td></tr><?php endforeach;?></table><?php endif;?></div></div></body></html>
